// Bun-native API server — validates incoming requests with the refined
// schemas generated by the `dv` CLI. No Vite, no framework: just Bun.serve.
import * as z from "zod";
import { createCustomerSchema, createOrderSchema } from "../shared/validators";

// In-memory "database".
const customers = new Map<
	string,
	{ id: string; email: string; fullName: string }
>();
const orders = new Map<
	string,
	{ id: string; customerId: string; totalCents: number }
>();

async function readJson(req: Request): Promise<unknown> {
	try {
		return await req.json();
	} catch {
		return null;
	}
}

function json(data: unknown, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "Content-Type": "application/json" },
	});
}

/** Testable request handler — exported so tests can call it without binding a port. */
export async function handleRequest(req: Request): Promise<Response> {
	const url = new URL(req.url);

	if (req.method === "POST" && url.pathname === "/api/customers") {
		const body = await readJson(req);
		const result = createCustomerSchema.safeParse(body);
		if (!result.success) {
			return json({ error: z.flattenError(result.error) }, 400);
		}
		const { email, fullName } = result.data;
		if (customers.has(email)) {
			return json(
				{
					error: {
						formErrors: [],
						fieldErrors: { email: ["Email is already registered"] },
					},
				},
				409,
			);
		}
		const id = crypto.randomUUID();
		customers.set(email, { id, email, fullName });
		return json({ ok: true, customer: { id, email, fullName } }, 201);
	}

	if (req.method === "POST" && url.pathname === "/api/orders") {
		const body = await readJson(req);
		const result = createOrderSchema.safeParse(body);
		if (!result.success) {
			return json({ error: z.flattenError(result.error) }, 400);
		}
		const { customerId, totalCents } = result.data;
		const id = crypto.randomUUID();
		orders.set(id, { id, customerId: customerId ?? id, totalCents });
		return json(
			{ ok: true, order: { id, customerId: customerId ?? id, totalCents } },
			201,
		);
	}

	if (req.method === "GET" && url.pathname === "/api/health") {
		return json({ ok: true });
	}

	return json({ error: "Not found" }, 404);
}

const server = Bun.serve({
	port: process.env.PORT ? Number(process.env.PORT) : 3000,
	fetch: handleRequest,
});

console.log(`Bun API listening on http://localhost:${server.port}`);
